// Package sdkproviders contains trusted, application-owned SDK provider
// bundles embedded into the Go server. Bundles are generated by the
// scripts/build-go-sdk-bundles.sh script from the retained JS SDK
// integration packages in packages/integrations and kept in VCS so
// `go build` needs no external steps. User-provided JavaScript is never
// loaded by this package. YAML integrations are registered separately by
// the YAML integration loader and stay outside this catalog.
package sdkproviders

import (
	"context"
	"embed"
	"fmt"
	"strings"

	"github.com/andreasmolnardev/dashwise/apps/backend/internal/jsruntime"
	"github.com/andreasmolnardev/dashwise/apps/backend/internal/sdkmanager"
)

//go:embed bundles/*.cjs
var bundleFS embed.FS

// Providers lists the embedded provider IDs in stable catalog order. Each
// entry must match its integration definition id and the generated
// bundles/<id>.cjs file name.
var Providers = []string{"groovewise", "homeassistant", "jellyfin", "music-assistant"}

// Bundle returns the embedded CommonJS bundle for a provider ID, mirroring
// how the lifecycle manager resolves an instance's Source value.
func Bundle(id string) ([]byte, error) {
	id = strings.TrimSpace(id)
	for _, provider := range Providers {
		if !strings.EqualFold(provider, id) {
			continue
		}
		bundle, err := bundleFS.ReadFile("bundles/" + provider + ".cjs")
		if err != nil {
			return nil, fmt.Errorf("embedded SDK provider %q is missing its bundle: %w", provider, err)
		}
		return bundle, nil
	}
	return nil, fmt.Errorf("%w: %q", sdkmanager.ErrBundleNotFound, id)
}

// BundleNames lists the generated .cjs bundle asset names in catalog order.
func BundleNames() []string {
	names := make([]string, 0, len(Providers))
	for _, provider := range Providers {
		names = append(names, provider+".cjs")
	}
	return names
}

// Load returns the embedded bundle registry and its catalog manifests, one
// per provider. Every manifest is read by evaluating only the trusted
// package definition; no lifecycle hooks run until the manager starts an
// enabled instance.
func Load(ctx context.Context) (sdkmanager.BundleMap, []jsruntime.Manifest, error) {
	bundles := make(sdkmanager.BundleMap, len(Providers))
	manifests := make([]jsruntime.Manifest, 0, len(Providers))
	for _, provider := range Providers {
		bundle, err := bundleFS.ReadFile("bundles/" + provider + ".cjs")
		if err != nil {
			return nil, nil, fmt.Errorf("read embedded %s SDK bundle: %w", provider, err)
		}
		instance, err := jsruntime.Load(ctx, bundle, jsruntime.Options{InstanceID: "catalog-" + provider})
		if err != nil {
			return nil, nil, fmt.Errorf("read embedded %s SDK manifest: %w", provider, err)
		}
		manifest := instance.Manifest()
		if manifest.ID != provider {
			return nil, nil, fmt.Errorf("embedded %s SDK bundle declares unexpected id %q", provider, manifest.ID)
		}
		bundles[provider] = bundle
		manifests = append(manifests, manifest)
	}
	return bundles, manifests, nil
}
